"""NPU AOT helpers called from ``triton.tools.compile`` and ``triton.tools.link``.

The upstream tools stay backend-agnostic: for ``--backend npu`` they delegate
to this module instead of carrying NPU-specific logic inline.

Keep this module import-light: ``link.py`` imports it unconditionally, and
the backend imports are resolved lazily inside ``prepare_params``.
"""


def c_sig_pattern():
    """Regex for the per-kernel C signature carried by ``tt-linker`` directives.

    NPU signatures spell pointer arguments as ``void*``; the upstream pattern
    only accepts ``\\w+`` type names, so this generalization also matches the
    trailing ``*``. It is a strict superset of the upstream pattern.
    """
    return "[\\s]*(\\w+\\*?)\\s+(\\w+)[,]?"


def hint_condition(val, hint, ty):
    """C text for one hint-dispatch check.

    NPU signatures spell pointer arguments as ``void*``, which cannot take
    integer arithmetic directly: cast their address through ``uintptr_t``
    for the divisibility/equality checks. Non-pointer arguments keep the
    upstream ``%``/``==`` spelling.
    """
    if ty == "void*":
        return (f"((uintptr_t){val} % {hint} == 0)" if hint == 16 else f"((uintptr_t){val} == {hint})")
    if hint == 16:
        return f"({val} % {hint} == 0)"
    if hint == 1:
        return f"({val} == {hint})"
    return None


def prepare_params(ccinfo, kernel, signature, constants, out_path, params, arg_names_not_1):
    """Adapt compile.py's template params for the NPU AOT C stubs.

    Exports the fixed C launcher next to the generated stubs and fills the
    params consumed by the ``compile.c`` / ``compile.h`` templates.
    """
    import dataclasses
    import shutil

    from triton.backends.ascend import launcher
    from triton.backends.ascend.driver import NPUUtils

    npu_utils = NPUUtils()
    spec = launcher.make_launch_spec(ccinfo.metadata, npu_utils)
    # A plain C process has no torch task queue: strip the framework-only
    # flag so the launcher runs the kernel directly instead of submitting
    # through npu_utils' OpCommand path.
    spec = dataclasses.replace(spec, flags=spec.flags & ~launcher.TASKQUEUE)
    index = lambda name: kernel.arg_names.index(name)
    types = launcher.argument_types({index(name): ty
                                     for name, ty in signature.items()}, {index(name)
                                                                          for name in constants})
    _, runtime_path = launcher.get_runtime(npu_utils.get_so_path())
    shutil.copy(launcher.export_launcher(spec, types, runtime_path), out_path.parent / "launcher_export.so")
    params["register_kernel_name"] = ccinfo.metadata.kernel_name
    params["packed_kernel_name"] = ccinfo.packed_metadata["kernel_name"]
    # CANN >= 9.1 launches kernels through aclrtLaunchKernelWithHostArgs;
    # the stub must register the embedded binary with the matching ACL
    # binary-load API: an rt-style function stub is not a valid
    # aclrtFuncHandle and would crash the launch.
    if launcher.utils.is_cann_version_at_least(9, 1, 0):
        params["use_acl_load"] = "1"
        params["acl_magic"] = ("ACL_RT_BINARY_MAGIC_ELF_VECTOR_CORE"
                               if ccinfo.metadata.mix_mode == "aiv" else "ACL_RT_BINARY_MAGIC_ELF_AICORE")
    else:
        params["use_acl_load"] = "0"
        params["acl_magic"] = "ACL_RT_BINARY_MAGIC_ELF_AICORE"
    params["magic"] = ("RT_DEV_BINARY_MAGIC_ELF_AIVEC"
                       if ccinfo.metadata.mix_mode == "aiv" else "RT_DEV_BINARY_MAGIC_ELF")
    params["arg_pointers"] = ", ".join([f"&{arg}" for arg in arg_names_not_1])
    params["arg_sizes"] = ", ".join([f"sizeof({arg})" for arg in arg_names_not_1])
    params["num_args"] = len(arg_names_not_1)


def c_types_include():
    """Header text providing the NPU result/stream stand-ins.

    The generated sources expose a CUDA-style C API surface; the NPU
    toolchain ships no CUDA headers, so link.py emits these self-contained
    stand-ins instead (guarded so the per-kernel headers generated by
    compile.py can be included alongside this one).
    """
    return "\n".join([
        "#include <stdint.h>",
        "",
        "#ifndef TT_AOT_KERNEL_TYPES",
        "#define TT_AOT_KERNEL_TYPES",
        "typedef int NPUresult;",
        "typedef void *NPUstream;",
        "#define ASCEND_SUCCESS 0",
        "#define ASCEND_ERROR_UNKNOWN 1",
        "#define ASCEND_ERROR_INVALID_VALUE 2",
        "#endif",
    ])


def rewrite_types(text):
    """Replace the CUDA-style type spellings in generated sources with the
    NPU stand-ins defined by ``c_types_include``."""
    return (text.replace("CUresult", "NPUresult").replace("CUstream",
                                                          "NPUstream").replace("CUDA_ERROR_INVALID_VALUE",
                                                                               "ASCEND_ERROR_INVALID_VALUE"))
